package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import it.cavallium.rockserver.core.impl.rocksdb.ReplicatedRangeStore;
import java.io.*;
import java.nio.ByteBuffer;
import java.util.*;

/** Fresh source progress without exporting or recapturing an immutable range image. */
public final class RatisSourceHeadRpc {
    public static final int KIND=117,MAX_REQUEST_BYTES=ScopedTransactionRpc.HEADER_BYTES+20+RatisTopologySourceSnapshotRpc.MAX_REQUEST_BYTES;
    public static final int MAX_REPLY_BYTES=ScopedTransactionRpc.HEADER_BYTES+100+RatisCatalogue.MAX_DIRECTORY_BYTES+RatisTopologySourceSnapshotRpc.MAX_OWNER_BYTES+65536;
    private RatisSourceHeadRpc() {}
    public record Request(RatisTopologySourceSnapshotRpc.Request source,ApplyPosition minimumImageCut) {
        public Request {Objects.requireNonNull(source);Objects.requireNonNull(minimumImageCut);if(minimumImageCut.term()<1)throw new IllegalArgumentException("Source head requires actual image cut");}
    }
    public record Head(Request request,ApplyPosition catalogueCut,RangeDirectory currentDirectory,ReplicaDescriptor sourceOwner,ApplyPosition completedCut,ReplicatedRangeStore.Configuration configuration) {
        public Head {Objects.requireNonNull(request);Objects.requireNonNull(catalogueCut);Objects.requireNonNull(currentDirectory);Objects.requireNonNull(sourceOwner);Objects.requireNonNull(completedCut);Objects.requireNonNull(configuration);var scope=request.source();if(catalogueCut.term()<1 || !currentDirectory.clusterId().equals(scope.clusterId()) || !currentDirectory.databaseId().equals(scope.databaseId()) || !currentDirectory.domainId().equals(scope.domainId()) || sourceOwner.role()!=ReplicaDescriptor.Role.VOTER || !RatisRelocationOwnerRpc.covers(completedCut,request.minimumImageCut()) || configuration.term()>completedCut.term() || configuration.index()>completedCut.index() || configuration.index()==completedCut.index() && configuration.term()!=completedCut.term())throw new IllegalArgumentException("Source head crossed authority/native prefix");if(scope.metadataOnly() || scope.relocation()){if(!scope.sourceOwner(sourceOwner))throw new IllegalArgumentException("Metadata source owner changed");}else if(!scope.relocation()){var current=requireContinuity(scope,currentDirectory);if(!current.replicas().contains(sourceOwner))throw new IllegalArgumentException("Head source is not a current voter");}if(!scope.relocation()){try{RatisRangeStateMachine.requireSchemaMembership(scope.metadataOnly()?scope.range():requireContinuity(scope,currentDirectory),configuration.data());}catch(IOException invalid){throw new IllegalArgumentException("Source head configuration membership differs",invalid);}}}
    }
    static RangeDescriptor requireContinuity(RatisTopologySourceSnapshotRpc.Request source,RangeDirectory current) {
        var original=source.range();var range=current.ranges().stream().filter(r->r.groupId().equals(source.sourceGroup())).findFirst().orElseThrow(()->new IllegalArgumentException("Source group retired; rediscover current placement"));
        if(!current.clusterId().equals(source.clusterId()) || !current.databaseId().equals(source.databaseId()) || !current.domainId().equals(source.domainId()) || !range.rangeId().equals(original.rangeId()) || range.rangeEpoch()!=original.rangeEpoch() || !Arrays.equals(range.lowerInclusive(),original.lowerInclusive()) || !Arrays.equals(range.upperExclusive(),original.upperExclusive()) || range.topologyState()!=RangeDescriptor.TopologyState.ACTIVE || !range.replicas().contains(source.receiver()))throw new IllegalArgumentException("Source geometry/receiver identity changed; rediscover placement");return range;
    }
    public static byte[] request(Request r){byte[] scope=RatisTopologySourceSnapshotRpc.request(RatisTopologySourceSnapshotRpc.PREPARE,r.source());return ScopedTransactionRpc.frame(KIND,ByteBuffer.allocate(20+scope.length).putInt(scope.length).put(scope).putLong(r.minimumImageCut().term()).putLong(r.minimumImageCut().index()).array());}
    public static Request request(byte[] bytes){var p=ScopedTransactionRpc.parse(bytes,MAX_REQUEST_BYTES);var b=ByteBuffer.wrap(p.body());if(p.kind()!=KIND || b.remaining()<20)throw new IllegalArgumentException("Invalid source head request");byte[] scope=blob(b,RatisTopologySourceSnapshotRpc.MAX_REQUEST_BYTES);if(b.remaining()!=16)throw new IllegalArgumentException("Invalid source head image cut");var result=new Request(RatisTopologySourceSnapshotRpc.request(scope),new ApplyPosition(b.getLong(),b.getLong()));if(!Arrays.equals(bytes,request(result)))throw new IllegalArgumentException("Noncanonical source head request");return result;}
    public static byte[] reply(Head h){try{var bytes=new ByteArrayOutputStream();var o=new DataOutputStream(bytes);o.write(OperatorUpload.sha256(request(h.request())));o.writeLong(h.catalogueCut().term());o.writeLong(h.catalogueCut().index());put(o,RangeDirectoryCodec.encode(h.currentDirectory()));put(o,RatisTopologySourceSnapshotRpc.owner(h.sourceOwner()));o.writeLong(h.completedCut().term());o.writeLong(h.completedCut().index());o.writeLong(h.configuration().term());o.writeLong(h.configuration().index());put(o,h.configuration().data());o.flush();return ScopedTransactionRpc.frame(KIND,bytes.toByteArray());}catch(IOException impossible){throw new AssertionError(impossible);}}
    public static Head reply(byte[] bytes,Request expected){var p=ScopedTransactionRpc.parse(bytes,MAX_REPLY_BYTES);var b=ByteBuffer.wrap(p.body());if(p.kind()!=KIND || b.remaining()<96)throw new IllegalArgumentException("Invalid source head reply");byte[] identity=new byte[32];b.get(identity);if(!Arrays.equals(identity,OperatorUpload.sha256(request(expected))))throw new IllegalArgumentException("Source head original scope/image cut changed");var cat=new ApplyPosition(b.getLong(),b.getLong());var directory=RangeDirectoryCodec.decode(blob(b,RatisCatalogue.MAX_DIRECTORY_BYTES));var owner=RatisTopologySourceSnapshotRpc.owner(blob(b,RatisTopologySourceSnapshotRpc.MAX_OWNER_BYTES));if(b.remaining()<36)throw new IllegalArgumentException("Truncated source head configuration");var cut=new ApplyPosition(b.getLong(),b.getLong());var cfg=new ReplicatedRangeStore.Configuration(b.getLong(),b.getLong(),blob(b,65536));if(b.hasRemaining())throw new IllegalArgumentException("Trailing source head bytes");return new Head(expected,cat,directory,owner,cut,cfg);}
    private static void put(DataOutputStream o,byte[] b)throws IOException{o.writeInt(b.length);o.write(b);}private static byte[] blob(ByteBuffer b,int max){if(b.remaining()<4)throw new IllegalArgumentException("Truncated source head field");int n=b.getInt();if(n<0 || n>max || n>b.remaining())throw new IllegalArgumentException("Source head field exceeds bound");byte[] result=new byte[n];b.get(result);return result;}
}
